    this.onWeekCHange.emit(WeekChange.NEXT);
  }

  getFirstOrLastWeek(value: FistLastWeek): void {
    this.onGetFirstOrLastWeek.emit(value);
  }

  addEvent(): void {
    let currentTime = this.now;
