import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent {
  title = 'AngularEventify';
  constructor() {}
  onEventCreated(event: {
    id?: string;
    name: string;
    startTime: string;
    endTime: string;
    date: string;
    description: string;
  }): void {
    console.log('Event created successfully: ', event);
  }

  onEventUpdated(event: {
    id?: string;
    name: string;
    startTime: string;
    endTime: string;
    date: string;
    description: string;
  }): void {
    console.log('Event updated successfully: ', event);
  }

  onEventDeleted(eventData: {
    name: string,
    id: string
  }): void {
    console.log('Deleted event info: ', eventData);
  }

  onEventCreationFailed(errorMessage: string): void {
    console.log('Event cration error: ', errorMessage);
  }

  onEventUpdateFailed(errorMessage: string): void {
    console.log('Event update error: ', errorMessage);
  }

  onEventDeleteFailed(errorMessage: string): void {
    console.log('Event delete error: ', errorMessage);
  }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'storybook-button',
  template: ` <button
    type="button"
    (click)="onClick.emit($event)"
    [ngClass]="classes"
    [ngStyle]="{ 'background-color': backgroundColor }"
  >
    {{ label }}
  </button>`,
  styleUrls: ['./button.css'],
})
export default class ButtonComponent {
  /**
   * Is this the principal call to action on the page?
   */
  @Input()
  primary = false;

  /**
   * What background color to use
   */
  @Input()
  backgroundColor?: string;

  /**
   * How large should the button be?
   */
  @Input()
  size: 'small' | 'medium' | 'large' = 'medium';

  /**
   * Button contents
   *
   * @required
   */
  @Input()
  label = 'Button';

  /**
   * Optional click handler
   */
  @Output()
  onClick = new EventEmitter<Event>();

  public get classes(): string[] {
    const mode = this.primary ? 'storybook-button--primary' : 'storybook-button--secondary';

    return ['storybook-button', `storybook-button--${this.size}`, mode];
  }
}

